from collections import Counter

# Score categories.
# Using descriptive string values for categories, as is common practice.
YACHT = "YACHT"
ONES = "ONES"
TWOS = "TWOS"
THREES = "THREES"
FOURS = "FOURS"
FIVES = "FIVES"
SIXES = "SIXES"
FULL_HOUSE = "FULL_HOUSE"
FOUR_OF_A_KIND = "FOUR_OF_A_KIND"
LITTLE_STRAIGHT = "LITTLE_STRAIGHT"
BIG_STRAIGHT = "BIG_STRAIGHT"
CHOICE = "CHOICE"


def score(dice, category):
    """
    Calculates the score of five dice for a given category in the game of Yacht.

    :param dice: A tuple or list of five integers, representing the dice values (1-6).
    :param category: A string representing the scoring category.
    :return: An integer score for the given dice and category.
    """

    counts = Counter(dice)  # Counts occurrences of each die face
    sorted_dice = sorted(dice)  # Sorted dice for straight checks
    total_sum = sum(dice)  # Sum of all dice, used for several categories

    if category == ONES:
        return counts[1] * 1
    elif category == TWOS:
        return counts[2] * 2
    elif category == THREES:
        return counts[3] * 3
    elif category == FOURS:
        return counts[4] * 4
    elif category == FIVES:
        return counts[5] * 5
    elif category == SIXES:
        return counts[6] * 6
    elif category == CHOICE:
        return total_sum
    elif category == YACHT:
        # Yacht: All five dice showing the same face.
        # This means there should be only one distinct die value.
        if len(counts) == 1:
            return 50
        else:
            return 0
    elif category == FULL_HOUSE:
        # Full House: Three of one number and two of another.
        # This requires exactly two distinct die values, one with count 3 and one with count 2.
        if len(counts) == 2 and sorted(counts.values()) == [2, 3]:
            return total_sum
        else:
            return 0
    elif category == FOUR_OF_A_KIND:
        # Four of a Kind: At least four dice showing the same face.
        # The score is the total of the four matching dice (face_value * 4).
        for face_value, count in counts.items():
            if count >= 4:
                return face_value * 4
        return 0  # No four of a kind found
    elif category == LITTLE_STRAIGHT:
        # Little Straight: 1-2-3-4-5.
        # All dice must be these specific values and distinct, which sorted_dice checks.
        if sorted_dice == [1, 2, 3, 4, 5]:
            return 30
        else:
            return 0
    elif category == BIG_STRAIGHT:
        # Big Straight: 2-3-4-5-6.
        # All dice must be these specific values and distinct, which sorted_dice checks.
        if sorted_dice == [2, 3, 4, 5, 6]:
            return 30
        else:
            return 0
    else:
        # Fallback for any unexpected category, though all valid categories should be covered.
        return 0

